The solver checks row, column, and box constraints before recursively filling the next empty cell.

def is_valid(puzzle, i, j, n):
    for k in range(9):
        if puzzle[i][k] == n or puzzle[k][j] == n:
            return False
    for k in range(3):
        for l in range(3):
            if puzzle[(i // 3) * 3 + k][(j // 3) * 3 + l] == n:
                return False
    return True

