def infer(possible_values, i, j, n):
    for k in range(9):
        if n in possible_values[(i, k)]:
            possible_values[(i, k)].remove(n)
            if len(possible_values[(i, k)]) == 0:
                return False
        if n in possible_values[(k, j)]:
